-- V90.cv: Advanced procurement analytics and supplier optimization.
CREATE TABLE IF NOT EXISTS procurement_supplier_analytics (analytics_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,supplier_id TEXT NOT NULL,period_key TEXT NOT NULL,spend_value NUMERIC NOT NULL DEFAULT 0,ppv_value NUMERIC NOT NULL DEFAULT 0,purchase_qty NUMERIC NOT NULL DEFAULT 0,contracted_rate NUMERIC NOT NULL DEFAULT 0,actual_rate NUMERIC NOT NULL DEFAULT 0,landed_cost NUMERIC NOT NULL DEFAULT 0,otif_pct NUMERIC NOT NULL DEFAULT 0,quality_rejection_pct NUMERIC NOT NULL DEFAULT 0,dependency_pct NUMERIC NOT NULL DEFAULT 0,savings_value NUMERIC NOT NULL DEFAULT 0,score NUMERIC NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,supplier_id,period_key));
CREATE TABLE IF NOT EXISTS procurement_supplier_recommendation (recommendation_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,item_master_id TEXT NOT NULL,supplier_id TEXT NOT NULL,period_key TEXT NOT NULL,score NUMERIC NOT NULL,rationale TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',approved_by TEXT,approved_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_proc_analytics_scope ON procurement_supplier_analytics(organization_id,entity_id,period_key,supplier_id);
